import heapq
from collections import defaultdict

def shortest_path(edges, start, end):
    """
    Find the shortest path between two nodes in a directed weighted graph.

    Args:
        edges: List of (from_node, to_node, weight) tuples representing one-way roads.
        start: Starting node.
        end: Destination node.

    Returns:
        A tuple (distance, path), where distance is the shortest total weight and 
        path is a list of nodes on the route. Returns (0, [start]) if start == end, 
        or (None, None) if no path exists.

    Raises:
        ValueError: If any edge has a negative weight.
    """
    # Same node case
    if start == end:
        return (0, [start])

    # Check for negative weights
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight not allowed")

    # Build adjacency list and collect all nodes
    graph = defaultdict(list)
    all_nodes = set()
    for from_node, to_node, weight in edges:
        graph[from_node].append((to_node, weight))
        all_nodes.add(from_node)
        all_nodes.add(to_node)

    # Handle isolated nodes (not connected to any edge)
    if start not in all_nodes or end not in all_nodes:
        return (None, None)

    # Dijkstra's algorithm
    distances = {node: float('inf') for node in all_nodes}
    predecessors = {}
    distances[start] = 0

    pq = [(0, start)]

    while pq:
        distance, current = heapq.heappop(pq)

        if distance > distances[current]:
            continue

        # Early exit if destination reached
        if current == end:
            break

        for neighbor, weight in graph[current]:
            new_distance = distances[current] + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                predecessors[neighbor] = current
                heapq.heappush(pq, (new_distance, neighbor))

    # No path found
    if distances[end] == float('inf'):
        return (None, None)

    # Reconstruct path from end to start using predecessor dictionary
    path = []
    current = end
    while True:
        path.append(current)
        if current == start:
            break
        current = predecessors[current]

    path.reverse()

    return (distances[end], path)
